  connectedCallback(){this._fit=()=>{const area=this.querySelector('.aba-content'),canvas=this.querySelector('.aba-canvas');if(area&&canvas)canvas.style.transform=`scale(${Math.min(area.clientWidth/1136.64,area.clientHeight/557.28)})`;};this._observer=new ResizeObserver(this._fit);this._observer.observe(this);this._fit();this._visibility=()=>this._motion(!this.ownerDocument.hidden);this.ownerDocument.addEventListener('visibilitychange',this._visibility);this._visibility();}
