const brandTerms={'Google Apps Script':'apps-script','Google Sheets':'sheets','Apps Script':'apps-script','OpenAI':'openai','ChatGPT':'chatgpt','GPT Store':'chatgpt','Custom GPT':'chatgpt','custom GPTs':'chatgpt','custom GPT':'chatgpt','GPT-6.2 Astra':'openai','GPT-6.2 Sol':'openai','GPT-1':'openai','GPT-2':'openai','GPT-3':'openai','GPT-4':'openai','GPTs':'chatgpt','GPT':'openai'};
