 if(s.titleLines){title.setAttribute('aria-label',s.title);s.titleLines.forEach(line=>{const span=el('span','titleLine');span.textContent=line;text.append(span);});}else text.textContent=s.title;
 const leading=s.title.startsWith('OpenAI')?'openai':s.title.startsWith('ChatGPT')?'chatgpt':null,tools=[...new Set([...(leading?[leading]:[]),...(s.tools||[])])];
 if(tools.length){const group=el('span','headingIcons');tools.forEach(name=>group.append(icon(name)));title.append(group);}if(s.risks){text.textContent=s.title.slice(0,-8);const risk=button('',()=>{const canvas=title.closest('.aba-canvas'),panel=el('section','topicOverlay aba-panel evidenceSource evidenceRisk');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',s.risks.title);const close=button('Close',()=>closePanel(canvas,panel,risk));close.setAttribute('aria-label','Close risk');const header=el('header','evidenceSourceHeading');header.append(el('h2','',s.risks.title),close);const link=el('a','evidenceOriginal','Open original source');link.href=s.views[0].source.url+'#page=51';link.target='_blank';link.rel='noopener noreferrer';const items=list(s.risks.items);for(const [index,item]of [...items.children].entries()){const copy=el('span','riskItemText',s.risks.items[index]),example=s.risks.cases[index],trigger=button('!',()=>showRiskCase(canvas,trigger,example));trigger.className='riskCaseTrigger';trigger.setAttribute('aria-label',(example.kind==='chat'?'Show chatbot example: ':example.kind==='scene'?'Show visual example: ':'Show real-world case: ')+s.risks.items[index].split(':')[0]);trigger.setAttribute('aria-haspopup','dialog');item.replaceChildren(copy,trigger);}panel.append(header,items);trapDialog(panel,close);openPanel(canvas,panel,close);});risk.className='evidenceRiskTrigger';risk.setAttribute('aria-label','Benefits and risks: open risks');risk.setAttribute('aria-haspopup','dialog');const normal=el('span','benefitsWord','benefits'),danger=el('span','riskWord','risks');normal.setAttribute('aria-hidden','true');danger.setAttribute('aria-hidden','true');risk.append(normal,danger);text.append(risk);}title.append(text);return title;
