function showRiskScene(canvas,trigger,example){
 const state=stateFor(example),requestId=window.eiuLessonRequestId,panel=el('section','topicOverlay aba-panel riskScene scene-'+example.scene);let ready=!requestId,epoch='';panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',example.title);
 const header=el('header','riskCaseHeading'),actions=el('div','riskCaseActions'),close=button('Close',()=>{cleanup();closePanel(canvas,panel,trigger);});close.setAttribute('aria-label','Close visual example');actions.append(close);header.append(el('h2','',example.title),actions);
 const world=el('div','riskSceneWorld');world.tabIndex=0;world.setAttribute('role','group');world.setAttribute('aria-label','Animated example. Click or press Space to continue.');const caption=el('div','riskSceneCaption');caption.setAttribute('aria-live','polite');caption.setAttribute('aria-atomic','true');const copy=el('p'),dots=el('div','sceneProgress');dots.setAttribute('aria-hidden','true');for(let i=0;i<4;i++)dots.append(el('span'));caption.append(copy,dots);
 const revealAt=(node,step)=>{node.dataset.revealAt=String(step);return node;};
 const station=(title,cls='')=>{const node=el('section','sceneStation '+cls);node.append(el('h3','',title));return node;};
 let flight,flightFrom,secondaryFlight,secondaryFrom;
 if(example.scene==='privacy'){
  const phone=station('Your phone'),device=el('div','scenePhone'),screen=el('div','scenePhoneScreen'),identity=el('div','sceneIdentity');identity.append(riskSceneArt('id'),el('strong','','ID CARD'));screen.append(el('p','','Make this fun!'),identity);device.append(screen);phone.append(device);
  const service=station('AI edit'),cloud=riskSceneArt('cloud'),stack=el('div','sceneEditStack'),uploaded=revealAt(el('div','sceneIDUpload'),1),edited=revealAt(el('div','sceneIDEdited'),2);uploaded.append(riskSceneArt('id'));edited.append(riskSceneArt('fun-id'),el('span','','Glasses + stickers'));stack.append(uploaded,edited);service.append(cloud,stack);
  const social=station('Social platforms'),post=revealAt(el('div','sceneSocialPost'),3),postHeader=el('div','scenePostHeader'),details=el('div','scenePostDetails');postHeader.append(el('strong','','Alex'),el('span','','Public'));for(const [label,value]of [['Name','Alex Sample'],['ID no.','SAMPLE-001']]){const field=el('div');field.append(el('span','',label),el('strong','',value));details.append(field);}post.append(postHeader,riskSceneArt('fun-id'),details,el('div','scenePostReactions','Like | Comment | Share'));social.append(post);world.append(phone,service,social);flight=uploaded;flightFrom=identity;secondaryFlight=post;secondaryFrom=edited;
 }else if(example.scene==='originality'){
  const original=station('Another bakery','sceneOriginal'),brand=el('div','sceneLogo');brand.append(riskSceneArt('sun'),el('strong','','SUNNY BAKES'));const complaint=revealAt(el('div','sceneComplaint','That is our logo!'),3);original.append(brand,complaint);
  const generated=station('Your AI design'),prompt=el('p','scenePrompt','Make my bakery a logo.'),design=revealAt(el('div','sceneLogo sceneGenerated'),1);design.append(riskSceneArt('sun'),el('strong','','MORNING BAKES'));generated.append(prompt,design);
  const shop=station('Your shop'),bag=revealAt(el('div','sceneBag'),2);bag.append(riskSceneArt('sun'),el('strong','','MORNING BAKES'));shop.append(bag);world.append(original,generated,shop);flight=bag;flightFrom=design;
 }else{
  const homework=station('At home'),paper=el('div','sceneHomework');paper.append(el('strong','sceneEquation','2x + 4 = 12'));const submitted=revealAt(el('div','sceneSubmitted'),2);submitted.append(el('strong','sceneEquation','x = 4'),el('span','sceneDoneMark',String.fromCharCode(10003)),el('strong','','SUBMITTED'));paper.append(submitted);homework.append(paper);
  const assistant=station('AI answer'),solution=revealAt(el('div','sceneMathSteps'),1);for(const line of ['2x + 4 = 12','2x = 8','x = 4'])solution.append(el('strong','',line));assistant.append(riskSceneArt('writing'),solution);
  const classroom=station('In class'),test=revealAt(el('div','sceneClassTest'),3);const board=el('div','sceneChalkboard');board.append(el('strong','','3x + 6 = 21'),el('span','','x = ?'));const student=el('div','sceneStudent');student.append(riskSceneArt('student'),el('strong','sceneBlankAnswer','...'));test.append(board,student);classroom.append(test);world.append(homework,assistant,classroom);flight=submitted;flightFrom=solution;

 }
 function fly(target,source){const a=source.getBoundingClientRect(),b=target.getBoundingClientRect(),scale=canvas.getBoundingClientRect().width/1136.64;animate(target,[{opacity:.3,transform:'translate('+((a.left-b.left)/scale)+'px,'+((a.top-b.top)/scale)+'px) scale(.65)'},{opacity:1,transform:'translate(0,0) scale(1)'}],620);}
 function paint(motion=false){const step=state.stage||0,previous=Number(panel.dataset.stage??-1);panel.dataset.stage=String(step);panel.dataset.sceneReady=String(ready);copy.textContent=example.captions[step];for(const [index,dot]of [...dots.children].entries())dot.dataset.active=String(index<=step);for(const node of world.querySelectorAll('[data-reveal-at]')){const reveal=Number(node.dataset.revealAt),visible=reveal<=step;node.dataset.revealed=String(visible);node.inert=!visible;node.setAttribute('aria-hidden',String(!visible));if(motion&&visible&&reveal>previous)animate(node,[{opacity:0,transform:'translateY(22px) scale(.94)'},{opacity:1,transform:'translateY(0) scale(1)'}],440);}if(motion&&flight&&((example.scene==='privacy'&&step===1)||(example.scene!=='privacy'&&step===2)))fly(flight,flightFrom);if(motion&&secondaryFlight&&step===3)fly(secondaryFlight,secondaryFrom);}

 function advance(){if(!ready||window.eiuSectionEnded||(state.stage||0)>=3)return;state.stage=(state.stage||0)+1;paint(true);if(requestId&&epoch)window.parent.postMessage({type:'eiu-risk-chat-save',requestId,exampleId:example.scene,epoch,count:state.stage},'*');}
 function receive(event){const message=event.data;if(event.source!==window.parent||message?.type!=='eiu-risk-chat-state'||message.requestId!==requestId||message.exampleId!==example.scene||!Number.isInteger(message.count)||message.count<0||message.count>3||typeof message.epoch!=='string'||window.eiuSectionEnded)return;state.stage=message.count;epoch=message.epoch;ready=true;paint();}
 function cleanup(){window.removeEventListener('message',receive);window.removeEventListener('pagehide',cleanup);}
 panel.addEventListener('click',event=>{if(!event.target.closest('button,a')&&!window.getSelection()?.toString())advance();});world.addEventListener('keydown',event=>{if(event.key===' '||event.key==='Enter'){event.preventDefault();advance();}});panel.append(header,world,caption);paint();trapDialog(panel,close);openPanel(canvas,panel,close);if(requestId){window.addEventListener('message',receive);window.addEventListener('pagehide',cleanup,{once:true});window.parent.postMessage({type:'eiu-risk-chat-load',requestId,exampleId:example.scene},'*');}
}
function showPracticeHint(canvas,trigger,text){const panel=el('section','topicOverlay aba-panel promptDefinition');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','You should use this prompt:');const close=button('\u00d7',()=>closePanel(canvas,panel,trigger));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent({kind:'prompt-definition',title:'You should use this prompt:',text},panel,canvas,close);trapDialog(panel,close);openPanel(canvas,panel,close);}
function showObjectives(canvas,trigger){
  const overlay=el('section','objectivesOverlay');overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Learning objectives');
  const header=el('header','objectivesHeading'),close=button('Close',()=>closePanel(canvas,overlay,trigger));close.setAttribute('aria-label','Close Learning objectives');header.append(el('h2','','Learning objectives'),close);
  const items=el('ol','objectivesList');for(const [number,text] of course.objectives){const item=el('li'),badge=el('strong','objectiveNumber',number);item.append(badge,el('span','objectiveText',text));items.append(item);}
  overlay.append(header,items);trapDialog(overlay,close);openPanel(canvas,overlay,close);
}
function pageContent(s,container,canvas,close){if(s.kind==='discussion-question'){container.classList.add('discussionQuestionPanel');if(close)container.append(close);container.append(heading(s,'discussionQuestion'));return;}if(!['cover','hub','split-overview'].includes(s.kind)){const header=el('header','slideHeader');header.append(heading(s));if(s.kind==='showcase'&&s.practice?.hint){const hint=button('Hint',()=>showPracticeHint(canvas,hint,s.practice.hint));hint.className='practiceHintButton';hint.setAttribute('aria-haspopup','dialog');header.append(hint);}if(close)header.append(close);container.append(header);}else if(close){close.classList.add('hubClose');container.append(close);}const body=el('div','body');container.append(body);renderBody(s,body,canvas);}
function renderHub(s,body,canvas){const hub=el('section','topicHub');hub.dataset.count=String(s.items.length);hub.setAttribute('aria-label',s.title);if(s.layout==='apps-script')hub.classList.add('appsScriptHub');if(s.layout==='visualization')hub.classList.add('visualizationHub');if(s.layout==='custom-ai')hub.classList.add('customAIHub');if(s.layout==='skill-examples')hub.classList.add('skillExamplesHub');const art=el('div','coverArt');art.innerHTML=course.coverArt;hub.append(art,heading(s,'hubTitle'));if(s.definition){hub.classList.add('promptHub');const help=button('?',()=>{let panel=hub._definition;if(!panel){panel=el('section','topicOverlay aba-panel promptDefinition');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',(s.definitionTitle||'What is a prompt?'));const close=button('\u00d7',()=>closePanel(canvas,panel,help));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent({kind:'prompt-definition',title:(s.definitionTitle||'What is a prompt?'),text:s.definition,ecosystem:s.ecosystem},panel,canvas,close);trapDialog(panel,close);hub._definition=panel;}openPanel(canvas,panel,panel.querySelector('.topicClose'));});help.className='promptHelp';help.setAttribute('aria-label',(s.definitionTitle||'What is a prompt?'));help.setAttribute('aria-haspopup','dialog');hub.append(help);}if(s.caution){hub.classList.add('useCasesHub');const alert=button('!',()=>{let panel=hub._caution;if(!panel){panel=el('section','topicOverlay aba-panel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Caution');const close=button('\u00d7',()=>closePanel(canvas,panel,alert));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent(s.caution,panel,canvas,close);trapDialog(panel,close);hub._caution=panel;}openPanel(canvas,panel,panel.querySelector('.topicClose'));});alert.className='cautionTrigger';alert.setAttribute('aria-label','Caution');alert.setAttribute('aria-haspopup','dialog');hub.append(alert);}const panels=new Map();s.items.forEach((item,index)=>{const trigger=button(item.label,()=>{let overlay=panels.get(index);if(!overlay){overlay=el('section','topicOverlay aba-panel');overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label',item.content.title);const close=button('×',()=>closePanel(canvas,overlay,trigger));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent(item.content,overlay,canvas,close);trapDialog(overlay,close);panels.set(index,overlay);}trigger.dataset.visited='true';openPanel(canvas,overlay,overlay.querySelector('[aria-label="Close topic"]'));});if(s.layout==='custom-ai'){trigger.textContent=item.label;if(item.content.kind==='skill-setup'&&item.content.tools?.[0])trigger.prepend(icon(item.content.tools[0]));}if(s.layout==='skill-examples'&&item.topicIcon){const mark=createCaseIcon(item.topicIcon);mark.classList.add('skillTopicIcon');trigger.prepend(mark);}trigger.className='hubButton';trigger.dataset.slot=String(index);trigger.setAttribute('aria-haspopup','dialog');hub.append(trigger);});body.append(hub);}
function historyLink(text,url,cls=''){const a=el('a',cls);a.textContent=text;a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function renderHistory(s,body,canvas){
 const cards=el('div','historyCards'),panels=new Map(),rows=new Map();
 for(const [key,title] of [['online','Online models'],['local','Local models']]){const group=el('section','historyGroup'),row=el('div','historyRow');group.setAttribute('aria-label',title);group.append(row);rows.set(key,row);cards.append(group);}
 s.items.forEach((item,index)=>{const trigger=button('',()=>{let panel=panels.get(index);if(!panel){panel=el('section','topicOverlay aba-panel historyPanel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',item.content.title);const close=button('×',()=>closePanel(canvas,panel,trigger));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent(item.content,panel,canvas,close);trapDialog(panel,close);panels.set(index,panel);}trigger.dataset.visited='true';openPanel(canvas,panel,panel.querySelector('.topicClose'));});
  trigger.className='historyCard';trigger.dataset.brand=item.icon;trigger.setAttribute('aria-label',item.label);trigger.setAttribute('aria-haspopup','dialog');
  const mark=el('span','historyMark'),name=el('strong','historyName'),family=el('span','historyFamily');name.textContent=item.label;family.textContent=item.family;mark.append(icon(item.icon));trigger.append(mark,name,family);rows.get(item.group||'online').append(trigger);
 });body.append(cards);
}
function renderHistoryDetail(s,body){
 const layout=el('div','historyDetail'),identity=el('aside','historyIdentity'),name=el('h2'),family=el('p');name.textContent=s.company;family.textContent=s.family;identity.append(icon(s.icon),name,family);
 const content=el('div','historyContent'),timeline=el('ol','historyEvents');
 for(const event of s.events){const row=el('li'),copy=el('div'),title=el('h3'),text=el('p');title.textContent=event.title;text.textContent=event.text;copy.append(title,text);const date=historyLink(event.date,event.url,'historyEventDate');date.setAttribute('aria-label',event.date+': '+event.title+' - official source');row.append(date,copy);timeline.append(row);}
 const market=el('section','historyMarket'),title=historyLink(s.marketTitle,s.marketUrl),text=el('p');text.textContent=s.marketText;market.append(title,text);content.append(timeline,market);layout.append(identity,content);body.append(layout);
}
function renderPlugins(s,body){
 const root=el('section','pluginsOverview'),intro=el('p','pluginsIntro'),grid=el('div','pluginsGrid');intro.textContent=s.intro;root.append(intro,grid);
 for(const platform of s.platforms){const card=el('section','pluginPlatform'),header=el('header'),name=el('h2'),term=el('p','pluginTerm'),examples=el('dl','pluginExamples');name.textContent=platform.name;term.textContent=platform.term;header.append(icon(platform.icon),name);card.append(header,term,examples);
  for(const [index,[label,description]] of platform.examples.entries()){const row=el('div'),title=el('dt'),text=el('dd'),name=el('span');name.textContent=label;title.append(icon(platform.exampleIcons[index]),name);text.textContent=description;row.append(title,text);examples.append(row);}
  grid.append(card);
 }body.append(root);
}
function renderSplitOverview(s,body,canvas){
 const split=el('section','aiSplitOverview'),models=el('section','aiModelHalf'),plugins=el('section','aiPluginHalf'),modelStage=el('div','aiModelStage'),pluginStage=el('div','aiPluginStage');
 models.setAttribute('aria-label','AI model');plugins.setAttribute('aria-label','Plugins');models.append(el('h1','','AI model'),modelStage);plugins.append(el('h1','','Plugins'),el('p','aiPluginIntro',s.items[1].content.intro),pluginStage);
 renderHistory(s.items[0].content,modelStage,canvas);
 for(const [index,platform] of s.items[1].content.platforms.entries()){
  let panel;const trigger=button('',()=>{if(!panel){panel=el('section','topicOverlay aba-panel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',platform.name+' integrations');const close=button('\u00d7',()=>closePanel(canvas,panel,trigger));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent({kind:'plugins',title:platform.name+' integrations',intro:s.items[1].content.intro,platforms:[platform]},panel,canvas,close);panel.classList.add('singlePluginPanel');trapDialog(panel,close);}trigger.dataset.visited='true';openPanel(canvas,panel,panel.querySelector('.topicClose'));});
  trigger.className='floatingPlugin';trigger.dataset.slot=String(index);trigger.setAttribute('aria-label',platform.name+' integrations');trigger.setAttribute('aria-haspopup','dialog');const header=el('span','floatingPluginHeading'),name=el('strong'),term=el('span','floatingPluginTerm'),examples=el('span','floatingPluginExamples');name.textContent=platform.name;term.textContent=platform.term;for(const [i,[label]] of platform.examples.entries()){const chip=el('span','pluginChip'),text=el('span');text.textContent=label.replace('Google ','').replace(' connector','').replace(' plugin','');chip.append(icon(platform.exampleIcons[i]),text);examples.append(chip);}header.append(icon(platform.icon),name);trigger.append(header,term,examples);pluginStage.append(trigger);
 }split.append(models,plugins);body.append(split);
}
function renderAnnotatedPrompt(s,body){
 const root=el('section','annotatedPrompt samplePrompt'),actions=el('div','annotationActions'),board=el('div','samplePromptBoard'),state=stateFor(s);let revealed=Boolean(state.revealed);
 const sync=()=>{state.revealed=revealed;root.dataset.revealed=String(revealed);reveal.setAttribute('aria-pressed',String(revealed));reveal.textContent=revealed?'Hide components':'Identify components';};
 const reveal=button('Identify components',()=>{revealed=!revealed;sync();});sync();actions.append(reveal);
 board.append(el('strong','samplePromptLabel','Prompt:'));
 for(const paragraph of s.paragraphs){const p=el('p',paragraph.className);for(const [text,bold] of paragraph.runs){if(bold){const strong=el('strong');strong.textContent=text;p.append(strong);}else p.append(document.createTextNode(text));}board.append(p);}
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('samplePromptArrows');svg.setAttribute('viewBox','0 0 1088 360');svg.setAttribute('aria-hidden','true');svg.innerHTML='<defs><marker id="sample-prompt-arrow" viewBox="0 0 6 6" refX="5" refY="3" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L6 3L0 6Z" fill="#17324a"/></marker></defs>';
 for(const annotation of s.annotations){const tag=el('span','componentLabel sampleComponentLabel');tag.textContent=annotation.component;tag.style.left=annotation.x+'px';tag.style.top=annotation.y+'px';board.append(tag);const line=document.createElementNS(svg.namespaceURI,'line');const [x1,y1,x2,y2]=annotation.line;for(const [name,value] of Object.entries({x1,y1,x2,y2,stroke:'#17324a','stroke-width':1.3,'marker-end':'url(#sample-prompt-arrow)'}))line.setAttribute(name,String(value));svg.append(line);}
 const tone=el('span','sampleTone');tone.textContent=s.tone;board.append(tone,svg);root.append(actions,board);body.append(root);
}
function demoLink(label,url){const a=historyLink('',url,'leaveDemo');a.append(icon('apps-script'),document.createTextNode(label));return a;}
function renderLeaveComparison(s,body){
 const root=el('section','leaveComparison'),bad=el('section','badPromptPanel'),good=el('section','goodPromptPanel'),badTitle=el('h2'),goodTitle=el('h2'),badText=el('p','badPromptText'),stage=el('section','goodPromptStage'),nav=el('nav','goodPromptNav');badTitle.textContent='Bad prompt';goodTitle.textContent='Good prompt';badText.textContent=s.bad;bad.append(badTitle,badText,demoLink('Open bad-prompt app',s.badUrl));
 const state=stateFor(s);let index=state.index||0;const previous=button('Previous part',()=>{index=Math.max(0,index-1);update();}),next=button('Next part',()=>{index=Math.min(s.pages.length-1,index+1);update();}),position=el('span','promptPartCount');nav.setAttribute('aria-label','Good prompt parts');nav.append(previous,position,next);
 function update(){state.index=index;const page=s.pages[index],title=el('h3');title.textContent=page.title;stage.replaceChildren(title);for(const text of page.paragraphs){const p=el('p');p.textContent=text;stage.append(p);}previous.disabled=index===0;next.disabled=index===s.pages.length-1;position.textContent=(index+1)+' / '+s.pages.length;}
 good.append(goodTitle,stage,nav,demoLink('Open good-prompt app',s.goodUrl));update();root.append(bad,good);body.append(root);
}
function createCaseIcon(name){
 const paths={game:'M7 7h10c2 0 3 2 3.5 4l1 6c.3 2-1.5 3-3 1l-3-3h-7l-3 3c-1.5 2-3.3 1-3-1l1-6C4 9 5 7 7 7ZM6 11h4m-2-2v4m7-2h.01m3 2h.01',document:'M7 3h8l4 4v14H5V3h2m8 0v5h5M8 12h8M8 16h6',idea:'M9 18h6m-5 3h4M8 14a7 7 0 1 1 8 0l-1 3H9l-1-3',check:'M4 12l5 5L20 5M4 21h16',mail:'M3 5h18v14H3ZM3 5l9 8 9-8',quiz:'M5 3h14v18H5ZM8 8h1m3 0h4M8 13h1m3 0h4M8 18h1m3 0h4',code:'M8 6l-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',chart:'M3 3v18h19M7 17v-5m5 5V7m5 10V4',travel:'M3 12l18-8-7 18-3-8-8-2Zm8 2 10-10',fitness:'M3 7v10m3-13v16m12-16v16m3-13v10M6 12h12',meal:'M5 3v6m4-6v6M3 6h8v4H3ZM7 10v11M17 3v18m0-18c5 3 5 8 0 10',reflection:'M3 4h18v13H10l-5 4v-4H3ZM7 9h10M7 13h7',learn:'M2 7l10-4 10 4-10 4-10-4Zm4 2v8c4 3 8 3 12 0V9m4-2v10'};
 const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.6');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');svg.classList.add('useCaseIcon');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',paths[name]);svg.append(path);return svg;
}
function renderUseCases(s,body){const grid=el('div','useCasesGrid');grid.dataset.layout=s.layout;for(const item of s.items){const card=el('section','useCaseCard'),copy=el('div'),title=el('h2'),text=el('p');title.textContent=item.title;text.textContent=item.text;copy.append(title,text);card.append(createCaseIcon(item.icon),copy);grid.append(card);}body.append(grid);}
function renderCaution(s,body){const root=el('section','cautionLayout'),warning=el('aside','cautionWarning'),symbol=el('strong','cautionSymbol','!'),message=el('p'),check=el('p','cautionCheck'),mail=el('section','academicEmail'),subject=el('strong','emailSubject'),salutation=el('p'),closing=el('p','emailClosing'),leftover=el('p','emailLeftover');message.textContent=s.warning;check.textContent=s.check;warning.append(symbol,message,check);subject.textContent=s.subject;salutation.textContent=s.salutation;mail.append(subject,salutation);for(const paragraph of s.paragraphs){const p=el('p');p.textContent=paragraph;mail.append(p);}closing.textContent=s.closing+'\n'+s.signature;leftover.textContent=s.leftover;mail.append(closing,leftover);root.append(warning,mail);body.append(root);}
function chart(rows,max=100){const root=el('div','chart');for(const[label,value,mark]of rows){const row=el('div','barRow'),name=el('span','barName'),track=el('div','track'),bar=el('div','bar');name.textContent=label;if(mark)name.prepend(icon(mark));bar.style.width=`${100*value/max}%`;track.setAttribute('aria-hidden','true');track.append(bar);row.append(name,track,el('strong','',`${value}%`));root.append(row);}const axis=el('div','axis');axis.append(el('span','','0%'),el('span','','50%'),el('span','','100%'));root.append(axis);return root;}
function renderEvidence(s,body,canvas){
 const root=el('section','evidence'),toolbar=el('div','evidenceToolbar'),nav=el('nav','evidenceTabs'),plot=el('section','evidencePlot'),state=stateFor(s),panels=new Map();let index=state.view||0;
 nav.setAttribute('aria-label','Data perspectives');
 const sourceButton=button('Source',()=>{
  const view=s.views[index];let panel=panels.get(index);
  if(!panel){
   panel=el('section','topicOverlay aba-panel evidenceSource');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','Source: '+view.label);
   const close=button('Close',()=>closePanel(canvas,panel,sourceButton));close.className='evidenceSourceClose';close.setAttribute('aria-label','Close source');
   const header=el('header','evidenceSourceHeading'),name=el('h2');name.textContent=view.source.title;header.append(name,close);
   const study=el('p','evidenceStudy');study.textContent=view.source.detail;
   const link=el('a','evidenceOriginal','Open original source');link.href=view.source.url;link.target='_blank';link.rel='noopener noreferrer';
   panel.append(header,el('h3','',view.title),study,link);trapDialog(panel,close);panels.set(index,panel);
  }
  openPanel(canvas,panel,panel.querySelector('.evidenceSourceClose'));
 });sourceButton.className='evidenceSourceButton';sourceButton.setAttribute('aria-haspopup','dialog');
 const tabs=s.views.map((view,i)=>{const tab=button('',()=>select(i));tab.textContent=view.label;if(view.icon)tab.prepend(icon(view.icon));return tab;});
 nav.append(...tabs);toolbar.append(nav,sourceButton);if(s.compact)root.classList.add('evidenceMarket');root.append(...(s.compact?[plot]:[toolbar,plot]));body.append(root);
 function select(i){index=i;state.view=i;tabs.forEach((tab,j)=>tab.setAttribute('aria-pressed',String(i===j)));const view=s.views[i],header=el('header','evidenceSummary'),title=el('h2');title.textContent=view.title;if(view.icon)title.prepend(icon(view.icon));header.append(title);if(s.compact)header.append(sourceButton);const bars=chart(view.rows);bars.setAttribute('aria-label',view.title);if(view.rowDetails)bars.querySelectorAll('.barRow').forEach((row,j)=>{const detail=view.rowDetails[j],trigger=button('',()=>{const panel=el('section','topicOverlay aba-panel evidenceSource evidenceTask');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',view.rows[j][0]);const close=button('Close',()=>closePanel(canvas,panel,trigger));close.setAttribute('aria-label','Close task details');const header=el('header','evidenceSourceHeading');header.append(el('h2','',view.rows[j][0]),close);panel.append(header,list(detail.items));trapDialog(panel,close);openPanel(canvas,panel,close);});trigger.className='barRow evidenceTaskButton';trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-label',view.rows[j][0]+' - '+view.rows[j][1]+'%: show tasks');trigger.append(...row.childNodes);row.replaceWith(trigger);});if(view.comparisons){const detail=el('section','marketDetail');detail.setAttribute('aria-live','polite');detail.setAttribute('aria-atomic','true');const rows=[...bars.querySelectorAll('.barRow')];function reveal(j){const data=view.comparisons[j];detail.replaceChildren(el('h3','',view.rows[j][0]));const total=el('strong','marketCurrency',String.fromCharCode(8776)+' $'+data.estimatedBillions.toFixed(1)+'B');detail.append(total);bars.querySelectorAll('.marketProvider').forEach((b,k)=>b.setAttribute('aria-pressed',String(k===j)));}rows.forEach((row,j)=>{const trigger=button('',()=>reveal(j));trigger.className='barRow evidenceTaskButton marketProvider';trigger.setAttribute('aria-label',view.rows[j][0]+': compare API spending share');trigger.append(...row.childNodes);trigger.addEventListener('pointerenter',()=>reveal(j));trigger.addEventListener('focus',()=>reveal(j));row.replaceWith(trigger);});reveal(0);plot.replaceChildren(header,detail,bars);}else plot.replaceChildren(header,bars);plot.dataset.view=String(i);}
 select(index);
}
function renderSpending(s,body,canvas){
 const root=el('section','spending'),toolbar=el('div','spendingToolbar'),nav=el('nav','spendingTabs'),stage=el('div','spendingStage'),state=stateFor(s);
 nav.setAttribute('aria-label','Spending perspectives');
 const labels=['API vs Subscription',...s.providers.map(p=>p.name),'Enterprise API spend'];
 function dialog(label,trigger,content){const panel=el('section','topicOverlay aba-panel spendingDetails');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',label);const close=button('Close',()=>closePanel(canvas,panel,trigger));close.setAttribute('aria-label','Close spending details');const header=el('header','spendingDetailHeading');header.append(el('h2','',label),close);panel.append(header,...content);trapDialog(panel,close);openPanel(canvas,panel,close);}
 const source=button('Source',()=>{const provider=s.providers[(state.spendingView||0)-1],sources=provider?provider.sources:s.providers.flatMap(p=>p.sources),links=el('div','spendingLinks');for(const [name,url]of sources){const link=el('a','',name);link.href=url;link.target='_blank';link.rel='noopener noreferrer';links.append(link);}dialog('Pricing sources',source,[el('p','','Checked '+s.checked+'. US personal plans, USD, monthly billing before tax. Regular prices; regional offers and eligibility can differ.'),el('p','','API prices are USD per 1M tokens, split into input and output. Subscription prices are USD per person per month, with usage limits. API rates use Standard text pricing and short-context requests. Tools, caching, long contexts and other media may add charges. Monthly app access and API billing remain separate meters; credits must be claimed when eligible.'),links]);});source.className='evidenceSourceButton';source.setAttribute('aria-haspopup','dialog');
 const tabs=labels.map((label,i)=>{const tab=button('',()=>select(i));tab.textContent=label;if(i>0&&i<=s.providers.length)tab.prepend(icon(s.providers[i-1].icon));return tab;});nav.append(...tabs);toolbar.append(nav,source);root.append(toolbar,stage);body.append(root);
 function select(i){state.spendingView=i;tabs.forEach((t,j)=>t.setAttribute('aria-pressed',String(i===j)));stage.replaceChildren();stage.dataset.view=String(i);source.hidden=i===labels.length-1;
  if(i===0){const columns=el('div','spendingColumns spendingOverview');for(const column of s.overview){const card=el('section','spendingCard'),title=el('h2','',column.title);card.append(title,list(column.bullets));columns.append(card);}stage.append(columns);return;}
  if(i===labels.length-1){renderEvidence({views:[s.market],compact:true},stage,canvas);return;}
  const p=s.providers[i-1],columns=el('div','spendingColumns'),api=el('section','spendingCard'),subscription=el('section','spendingCard'),models=el('div','spendingModels');api.append(el('h2','','API'));
  for(const [name,role,input,output]of p.api){const model=el('article','spendingModel'),title=el('h3','',name),prices=el('div','spendingRate');for(const [label,value]of [['Input',input],['Output',output]]){const rate=el('div','spendingRateCell');rate.append(el('span','',label),el('strong','','$'+value));prices.append(rate);}model.append(title,el('p','',role),prices);models.append(model);}const options=button('API options',()=>dialog(p.name+' API options',options,[list(p.apiOptions)]));options.className='spendingOptions';options.setAttribute('aria-haspopup','dialog');api.append(models,options);
  subscription.append(el('h2','','Subscription'));const plans=el('div','spendingPlans');for(const [name,price,benefit]of p.plans){const plan=el('article','spendingPlan');plan.append(el('h3','',name),el('strong','spendingPlanPrice',price),el('p','',benefit));plans.append(plan);}const credits=button('Included API credits',()=>dialog(p.name+' API credits',credits,[el('p','',p.credit)]));credits.className='spendingOptions spendingCreditsButton';credits.setAttribute('aria-haspopup','dialog');subscription.append(plans,credits);columns.append(api,subscription);stage.append(columns);
 }
 select(Math.min(state.spendingView||0,labels.length-1));
}
function renderAITool(s,body){
 const layout=el('section','aiToolLayout'),copy=el('div','aiToolCopy'),brand=el('a','aiToolBrand'),name=el('h2','',s.tool),figure=el('figure','aiToolFigure'),preview=el('a','aiToolPreview'),image=el('img','aiToolInterface'),visit=el('a','aiToolVisit',`Open ${s.tool} ↗`);
 for(const a of [brand,preview,visit]){a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';}
 brand.setAttribute('aria-label',`Open ${s.tool} official website`);brand.append(icon(s.icon),name);
 image.src=course.toolInterfaces[s.icon];image.alt=s.interfaceAlt;image.draggable=false;preview.append(image);preview.setAttribute('aria-label',`Open ${s.tool} from its interface preview`);
 figure.append(preview);
 copy.append(el('p','aiToolCategory',s.category),brand,el('p','aiToolDescription',s.description),visit);
 layout.append(copy,figure);body.append(layout);
}
function renderBody(s,body,canvas){
  if(s.kind==='skill-demo'){
   const root=el('section','skillDemo'),cards=el('div','skillDemoCards');root.append(el('p','skillDemoIntro',s.intro));s.features.forEach(([title,text],i)=>{const card=el('section','skillDemoCard');card.append(el('span','skillDemoNumber',String(i+1).padStart(2,'0')),el('h2','',title),el('p','',text));cards.append(card);});
   const asset=course.skillDemoFiles[s.download],save=button('Download SKILL.md',()=>download(asset.name,'base64:'+asset.mime,asset.data));save.className='skillDemoDownload';root.append(cards,save);body.append(root);return;
  }
  if(s.kind==='skill-setup'){const root=el('section','skillSetup'),steps=el('ol','skillSetupSteps');s.steps.forEach((text,i)=>{const step=el('li','skillSetupStep');step.append(el('span','skillStepNumber',String(i+1)),el('p','',text));steps.append(step);});root.append(steps);body.append(root);return;}
  if(s.kind==='try-code'){
   const root=el('section','tryCode'),grid=el('div','tryCodeGrid'),footer=el('div','tryCodeFooter'),status=el('p','tryCopyStatus'),state=stateFor(s),files=s.fileSet==='sales-dashboard'?course.salesDashboardFiles:course.tryFiles;grid.dataset.count=String(s.files.length);state.copiedFiles=state.copiedFiles||[];status.setAttribute('role','status');status.setAttribute('aria-live','polite');
   for(const name of s.files){
    const file=button('',()=>{state.copiedFiles=state.copiedFiles.filter(f=>f!==name);file.dataset.copied='false';copy(files[name],root,status,()=>{if(!state.copiedFiles.includes(name))state.copiedFiles.push(name);file.dataset.copied='true';status.textContent=name+' copied';file.focus();});});
    file.className='tryCodeFile';file.dataset.copied=String(state.copiedFiles.includes(name));file.setAttribute('aria-label','Copy '+name);
    const mark=el('span','tryFileMark','{ }'),check=el('span','tryCopiedMark','\u2713');mark.setAttribute('aria-hidden','true');check.setAttribute('aria-hidden','true');file.append(mark,el('strong','',name),check);grid.append(file);
   }
   const resources=el('div','tryResources');if(s.download){const asset=course.salesData,save=button('Download Sale data (.xlsx)',()=>download(asset.name,'base64:'+asset.mime,asset.data));save.className='tryEditorLink salesDataDownload';save.prepend(icon('sheets'));resources.append(save);}if(s.url){const link=el('a','tryEditorLink');link.textContent='Google Apps Script';link.prepend(icon('apps-script'));link.href=s.url;link.target='_blank';link.rel='noopener noreferrer';resources.append(link);}footer.append(resources,status);
   if(s.limitations){root.classList.add('salesTry');const stage=el('div','salesTryStage');let panel;const help=button('',()=>{if(!panel){panel=el('section','topicOverlay aba-panel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',s.limitations.title);const close=button('\u00d7',()=>closePanel(canvas,panel,help));close.className='topicClose';close.setAttribute('aria-label','Close topic');pageContent(s.limitations,panel,canvas,close);trapDialog(panel,close);}openPanel(canvas,panel,panel.querySelector('.topicClose'));});help.className='salesLimitTrigger';help.setAttribute('aria-label','What are the limitations?');help.setAttribute('aria-haspopup','dialog');const mark=el('span','salesLimitMark','?');mark.setAttribute('aria-hidden','true');help.append(mark);stage.append(grid,help);root.append(stage,footer);}else root.append(grid,footer);body.append(root);return;
  }
  if(s.kind==='gas-flow'){
   const root=el('section','gasFlow'),steps=el('ol','gasFlowSteps');
   s.steps.forEach(([title,text],i)=>{const item=el('li','gasFlowStep'),number=el('span','gasFlowNumber',String(i+1)),copy=el('div');copy.append(el('h2','',title),el('p','',text));item.append(number,copy);steps.append(item);});
   root.append(steps);body.append(root);return;
  }
  if(s.kind==='spending'){renderSpending(s,body,canvas);return;}
  if(s.kind==='evidence'){renderEvidence(s,body,canvas);return;}
  if(s.kind==='ai-tool'){renderAITool(s,body);return;}
  if(s.kind==='hub')renderHub(s,body,canvas);
  else if(s.kind==='split-overview')renderSplitOverview(s,body,canvas);
  else if(s.kind==='history')renderHistory(s,body,canvas);
  else if(s.kind==='plugins')renderPlugins(s,body);
  else if(s.kind==='use-cases')renderUseCases(s,body);
  else if(s.kind==='ai-caution')renderCaution(s,body);
  else if(s.kind==='annotated-prompt')renderAnnotatedPrompt(s,body);
  else if(s.kind==='leave-compare')renderLeaveComparison(s,body);
  else if(s.kind==='prompt-definition'){if(s.ecosystem)renderGASDefinition(s,body,canvas);else{const text=el('p','promptDefinitionText');text.textContent=s.text;body.append(text);}}
  else if(s.kind==='history-detail')renderHistoryDetail(s,body);
  else if(s.kind==='cover'){const cover=el('div','cover'),art=el('div','coverArt');art.innerHTML=course.coverArt;cover.append(art,el('h1','',s.title));const actions=el('div','actions'),objectives=button('Learning objectives',()=>showObjectives(canvas,objectives));actions.append(objectives);cover.append(actions);body.append(cover);}
  else if(s.kind==='showcase'){body.dataset.eiuShowcase='true';if(s.practice){const brief=el('section','practiceBrief'),steps=list(s.practice.steps,true);steps.className='practiceBriefSteps';brief.append(el('p','practiceBriefGoal',s.lead),steps,el('p','practiceBriefOnline','Open this slide in Learning to share your link or image and view the class board.'));body.append(brief);}}
}
function render(s){const root=document.createElement('eiu-aba-slide');root.className='slide aba-slide';root.dataset.eiuTemplate='system';root.dataset.mis311Frame='true';root.style.backgroundImage=`url(${JSON.stringify(course.frame)})`;root.setAttribute('aria-label',s.title);
  const content=el('div','aba-content');content.dataset.mis311Content='true';const canvas=el('main','aba-canvas');canvas.dataset.offlineCanvas='true';content.append(canvas);root.append(content);pageContent(s,canvas,canvas);const number=el('span','aba-page',String(s.number));number.dataset.mis311Page='true';root.append(number);return root;
}
exports.default = course.slides.map(s => () => render(s));
